graph = {
    "Falcon Cloud": [("supplies", "Acme Corp"), ("supplies", "Beta Inc")],
    "Acme Corp": [("produces", "Widget X")],
    "Beta Inc": [("produces", "Widget Y")],
}

def traverse(graph, start, relation_filter, max_hops=2):
    # bound the traversal depth
    paths = []
    frontier = [(start, [])]
    for hop in range(max_hops):
        next_frontier = []
        for node, path_so_far in frontier:
            for relation, neighbor in graph.get(node, []):
                if relation != relation_filter:
                    # only follow the relevant relationship type
                    continue
                new_path = path_so_far + [(node, relation, neighbor)]
                paths.append(new_path)
                next_frontier.append((neighbor, new_path))
        frontier = next_frontier
    return paths

# collect every path, not just the first
paths = traverse(graph, "Falcon Cloud", "supplies")
print("Traversal paths found:")
for path in paths:
    print(f"  {path}")

def format_path_for_model(path):
    # format a path as readable text for the model
    return " and ".join(f"{s} {r} {o}" for s, r, o in path)

print("\nFormatted for the model:")
for path in paths:
    print(f"  {format_path_for_model(path)}")
